SELECT COUNT(DISTINCT p.id) AS athlete_count
FROM person p JOIN games_competitor gc ON gc.person_id=p.id JOIN games g ON g.id=gc.games_id JOIN competitor_event ce ON ce.competitor_id=gc.id JOIN event e ON e.id=ce.event_id JOIN sport s ON s.id=e.sport_id
WHERE g.games_name='2008 Summer' AND s.sport_name='Canoeing' AND p.weight / (p.height * p.height) < 30;

