SELECT COUNT(CASE WHEN p.gender = 'F' THEN gc.person_id END) * 100.0 / COUNT(gc.person_id) AS percentage, COUNT(gc.person_id) AS total, COUNT(CASE WHEN p.gender = 'F' THEN gc.person_id END) AS women
FROM event e JOIN competitor_event ce ON ce.event_id=e.id JOIN games_competitor gc ON gc.id=ce.competitor_id JOIN person p ON p.id=gc.person_id
WHERE e.event_name='Equestrianism Mixed Three-Day Event, Individual';
